ReplayBuffer.sample.source:
def sample(self, batch_size: int, env: VecNormalize | None = None) -> ReplayBufferSamples:
    """
    Sample elements from the replay buffer.
    Custom sampling when using memory efficient variant,
    as we should not sample the element with index `self.pos`
    See https://github.com/DLR-RM/stable-baselines3/pull/28#issuecomment-637559274

    :param batch_size: Number of element to sample
    :param env: associated gym VecEnv
        to normalize the observations/rewards when sampling
    :return:
    """
    if not self.optimize_memory_usage:
        return super().sample(batch_size=batch_size, env=env)
    # Do not sample the element with index `self.pos` as the transitions is invalid
    # (we use only one array to store `obs` and `next_obs`)
    if self.full:
        batch_inds = (np.random.randint(1, self.buffer_size, size=batch_size) + self.pos) % self.buffer_size
    else:
        batch_inds = np.random.randint(0, self.pos, size=batch_size)
    return self._get_samples(batch_inds, env=env)

LinearPolicy.update.source:
def update(self, observation, action, reward, next_observation, terminated, alpha, gamma, next_action=None):
    if (type(action) is not int or action not in range(5) or not 0 < alpha <= 1
            or not 0 <= gamma <= 1 or not np.isfinite(reward)):
        raise ValueError('Invalid linear update')
    features = encode_features(observation)
    target = float(reward)
    if not terminated:
        values = self.scores(next_observation)
        if self.algorithm == 'sarsa':
            if type(next_action) is not int or next_action not in range(5):
                raise ValueError('SARSA needs its next behavior-policy action')
            target += gamma*values[next_action]
        else:
            target += gamma*values.max()
    error = target-self.weights[action] @ features
    self.weights[action] += alpha*error*features/float(features @ features)
    if not np.isfinite(self.weights).all(): raise FloatingPointError('Linear values diverged')

